use crate::aap::caps::inference_llm;

const OVERVIEW_MAX_BYTES: usize = 600;

const SYSTEM: &str = "You write a short overview for a daily digest of feed items. \
Use only the items provided. Reply with plain text and no markup.";

struct Node;

/// Truncate `s` to at most `max` bytes, cutting only at a char boundary.
/// Byte length <= 600 implies character length <= 600.
fn truncate_to_bytes(mut s: String, max: usize) -> String {
    if s.len() <= max {
        return s;
    }
    let mut end = max;
    while end > 0 && !s.is_char_boundary(end) {
        end -= 1;
    }
    s.truncate(end);
    s
}

impl Guest for Node {
    fn run(selected: Selection, info: RunInfo) -> Digest {
        let mut prompt = String::new();
        for entry in selected.entries.iter().filter(|e| e.kept) {
            prompt.push_str("- ");
            prompt.push_str(&entry.title);
            prompt.push_str(": ");
            prompt.push_str(&entry.summary);
            prompt.push('\n');
        }

        let raw = inference_llm::infer(SYSTEM, &prompt, "digest");
        let overview = truncate_to_bytes(raw, OVERVIEW_MAX_BYTES);

        Digest {
            date: info.date,
            overview,
            entries: selected.entries,
            considered: selected.considered,
        }
    }
}

export!(Node);
